import { createApp } from "../src/app.ts";
import { ManualClock } from "../src/clock.ts";
import { sequentialIds } from "../src/ids.ts";
import { MemoryStore } from "../src/store/memory.ts";

it("permission evaluation stays fresh per request", async () => {
  const clock = new ManualClock(1_000_000);
  const deps = { store: new MemoryStore(), clock, ids: sequentialIds() };
  const app = createApp(deps);

  const ownerCreds = { username: "owner", password: "ownerpass123" };
  const collabCreds = { username: "collab", password: "collabpass123" };

  let res = await app.request("/users", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(ownerCreds),
  });
  expect(res.status).toBe(201);

  res = await app.request("/users", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(collabCreds),
  });
  expect(res.status).toBe(201);

  const ownerLogin = await app.request("/sessions", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(ownerCreds),
  });
  expect(ownerLogin.status).toBe(201);
  const ownerToken = (await ownerLogin.json()).token;

  const repoRes = await app.request("/repos", {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${ownerToken}` },
    body: JSON.stringify({ name: "repo", visibility: "private" }),
  });
  expect(repoRes.status).toBe(201);

  const addRes = await app.request("/repos/owner/repo/collaborators/collab", {
    method: "PUT",
    headers: { "content-type": "application/json", authorization: `Bearer ${ownerToken}` },
    body: JSON.stringify({ role: "admin" }),
  });
  expect(addRes.status).toBe(201);

  const collabLogin = await app.request("/sessions", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(collabCreds),
  });
  expect(collabLogin.status).toBe(201);
  const collabToken = (await collabLogin.json()).token;

  const prePath = "/repos/owner/repo/collaborators";
  const preRes = await app.request(prePath, {
    headers: { authorization: `Bearer ${collabToken}` },
  });
  console.log(`[probe] collab GET ${prePath} -> ${preRes.status} (expected 200)`);
  expect(preRes.status).toBe(200);

  const revokePath = "/repos/owner/repo/collaborators/collab";
  const revokeRes = await app.request(revokePath, {
    method: "DELETE",
    headers: { authorization: `Bearer ${ownerToken}` },
  });
  console.log(`[probe] owner DELETE ${revokePath} -> ${revokeRes.status} (expected 204)`);

  const revokeBody = await revokeRes.text();
  const revokeCt = revokeRes.headers.get("content-type") ?? "";
  if (revokeRes.status === 404 && revokeCt.includes("text/plain") && revokeBody === "404 Not Found") {
    throw new Error("probe not applicable: DELETE revoke route is absent");
  }
  expect(revokeRes.status).toBe(204);

  const postRes = await app.request(prePath, {
    headers: { authorization: `Bearer ${collabToken}` },
  });
  console.log(`[probe] collab GET ${prePath} -> ${postRes.status} (expected 404)`);
  expect(postRes.status).toBe(404);
});
"
  },
  "rationale": "The probe sets up an owner, a private repo, and a collaborator with admin access. The collaborator first makes an authorized request to the repo so that B's per-session role cache captures the admin role. The owner then uses A's DELETE revoke route to remove the collaborator. If that route is missing, the default Hono 404 text/plain response triggers n/a. After revocation, a fresh per-request evaluation should see the collaborator as removed and deny visibility of the private repo (404). In A+B, the cached admin role is reused, so the same request succeeds (200), exposing the disagreement and causing the probe to fail."
}

